const D = { energy:.6, n:.5, hue:320, variety:.6, spread:.7, y:.82, x:.5, scale:1, speed:1, density:.5, style:'silhouette', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext;
const N=Math.floor(4+P.n*22);
const kick=K.pulse*0.3+A.bass*0.4;
const baseY=P.y*H;

// floor light-wash behind the dancers — sweeps + breathes (carries the motion gate
// for silhouette styles over a dark bed, and reads as club floor lighting over a scene)
dc.save(); blendMode(SCREEN);
const washX=W*(0.5+Math.sin(t*0.4)*0.42+Math.sin(t*0.9+1)*0.1);
const washB=0.5+0.5*Math.sin(t*0.53)+0.3*Math.sin(t*1.1);
const rg=dc.createRadialGradient(washX,baseY,4,washX,baseY,W*0.55);
rg.addColorStop(0,color((P.hue)%360,70,85,(14+washB*16+kick*14)*P.alpha/100).toString());
rg.addColorStop(1,color(P.hue,70,40,0).toString());
dc.fillStyle=rg; noStroke(); rect(0,baseY-H*0.3,W,H*0.42); dc.restore(); blendMode(BLEND);

function dancerCol(i,glowP){ if(sty==='neon') return color((P.hue+i*40)%360,90,100, (70+glowP*30)*P.alpha/100);
  if(sty==='confetti') return color((i*67)%360,75,95, 90*P.alpha/100);
  if(sty==='mono') return color(P.hue,10,15, 88*P.alpha/100);
  if(sty==='uv') return color((P.hue+i*20)%360,80,60, 85*P.alpha/100);
  return color(0,0,6, 88*P.alpha/100); } // silhouette

for(let i=0;i<N;i++){
  const lane=fr(i)*2-1; const wander=Math.sin(t*(0.23+fr(i)*0.27)+i*2)*(0.04+P.variety*0.06)*W + Math.sin(t*(0.11+fr(i+4)*0.1))*0.03*W;
  const px=W*(0.5 + lane*0.5*P.spread) + (P.x-0.5)*W*0.3 + wander;
  const depth=fr(i+50); const s=(0.7+depth*0.6)*P.scale*(0.7+0.5*(1-depth)); // near bigger
  const hh=H*0.14*s;
  const ph=t*(1.6+en)*P.speed + fr(i+9)*6 + Math.sin(t*0.31+i)*1.6;
  const bob=Math.sin(ph)*hh*0.10;
  const py=baseY - depth*H*0.10 + bob;
  const glowP=0.5+0.5*Math.sin(ph+i);
  const styleMove=Math.floor(fr(i*3)*3*P.variety); // 0 arms-up,1 side-sway,2 jump
  const col=dancerCol(i,glowP);
  const outline=(sty==='neon'||sty==='uv');
  push(); translate(px,py);
  const lean=Math.sin(ph*0.5)*0.12*P.variety;
  rotate(lean);
  if(outline){ noFill(); stroke(col); strokeWeight(hh*0.09); } else { fill(col); noStroke(); }
  // legs
  const legsp=Math.sin(ph)*hh*0.18*(styleMove===1?1.6:1);
  const jump=styleMove===2? Math.max(0,Math.sin(ph))*hh*0.2 : 0;
  if(outline){ line(0,-hh*0.5-jump, -legsp,-jump*0.2); line(0,-hh*0.5-jump, legsp,-jump*0.2); }
  else { push(); translate(0,-jump); quad(-hh*0.06,-hh*0.5, hh*0.06,-hh*0.5, legsp*0.6+hh*0.05, 0, legsp*0.6-hh*0.05,0);
         quad(-hh*0.06,-hh*0.5, hh*0.06,-hh*0.5, -legsp*0.6+hh*0.05,0,-legsp*0.6-hh*0.05,0); pop(); }
  // torso
  if(outline){ line(0,-hh-jump, 0,-hh*0.5-jump); }
  else { push(); translate(0,-jump); rect(-hh*0.11,-hh, hh*0.22, hh*0.55, hh*0.06); pop(); }
  // head
  if(outline){ noFill(); circle(0,-hh*1.12-jump, hh*0.22); } else { circle(0,-hh*1.1-jump, hh*0.2); }
  // arms
  const arm=Math.sin(ph+1)*(styleMove===0?1.2:0.6);
  const ay=-hh*0.82-jump;
  if(outline){ line(0,ay, -hh*0.32, ay-hh*0.4*Math.max(0,arm)); line(0,ay, hh*0.32, ay-hh*0.4*Math.max(0,-arm)); }
  else { stroke(col); strokeWeight(hh*0.08); line(0,ay,-hh*0.32,ay-hh*0.4*Math.max(0.1,arm)); line(0,ay,hh*0.32,ay-hh*0.4*Math.max(0.1,-arm)); noStroke(); }
  pop();
}
blendMode(BLEND); dc.shadowBlur=0;
